use std::io

fn main() {
    let text = io::read_to_string() ?? ""
    let lines = text.split("\n")
    let mut cap = 1
    let mut keys: Vec<int> = Vec::new()
    let mut vals: Vec<int> = Vec::new()
    let mut first = true
    for line in lines {
        let parts = line.split_whitespace().collect::<Vec<string>>()
        if parts.len() == 0 {
            continue
        }
        if first {
            cap = parts[0].parse::<int>() ?? 0
            first = false
            continue
        }
        let cmd = parts[0]
        if cmd == "put" {
            let k = parts[1].parse::<int>() ?? 0
            let v = parts[2].parse::<int>() ?? 0
            let mut i = 0
            while i < keys.len() {
                if keys[i] == k {
                    keys.remove(i)
                    vals.remove(i)
                    break
                }
                i += 1
            }
            keys.insert(0, k)
            vals.insert(0, v)
            if keys.len() > cap {
                let last = keys.len() - 1
                println("evict ${keys[last]}")
                keys.remove(last)
                vals.remove(last)
            }
        } else if cmd == "get" {
            let k = parts[1].parse::<int>() ?? 0
            let mut found = -1
            let mut i = 0
            while i < keys.len() {
                if keys[i] == k {
                    found = vals[i]
                    keys.remove(i)
                    vals.remove(i)
                    keys.insert(0, k)
                    vals.insert(0, found)
                    break
                }
                i += 1
            }
            println("${found}")
        } else if cmd == "keys" {
            if keys.len() == 0 {
                println("<empty>")
            } else {
                let mut out = ""
                let mut i = 0
                while i < keys.len() {
                    if i > 0 {
                        out = out + " "
                    }
                    out = out + keys[i].to_string()
                    i += 1
                }
                println("${out}")
            }
        }
    }
}

